-- =====================================================================
-- 02_import_registry.sql  —  logs/experiment_registry.json → experiment.runs
-- WHY: git-tracked SSOT인 실험 레지스트리를 DB로 적재해 조회/조인 가능하게 함.
-- 실행 순서: 01_schema.sql 적용 후. 멱등(ON CONFLICT)이라 재실행 안전.
-- 생성 방법: scripts/db/experiment_tracking/에서 registry JSON을 SQL로 내보낸 것.
--            (자격증명 없이 DBeaver에서 바로 실행 가능하게 하기 위함.
--             자격증명이 있으면 import_registry.py를 써도 결과가 같다.)
--
-- 주의: result_summary는 산문("Det AUC 0.793, Id F1 0.356")이며 그대로 저장한다.
--       run_metrics로 파싱하지 않는다 — 산문에서 지표를 뽑는 건 숫자를 지어내는 것.
-- 생성 시점 레지스트리 건수: 55
-- =====================================================================

BEGIN;

DO $$
BEGIN
    IF current_database() <> 'aecd_platform' THEN
        RAISE EXCEPTION
            'Wrong database: %. Connect to aecd_platform before running this script.',
            current_database();
    END IF;
END
$$;

